// === Archer Job Raporu: 3 sheet'li Excel üretimi ===
// Girdi: her item = bir /jobs/{job_id}/ detay yanitindaki "data" objesi (samples dahil)
// require('xlsx') icin self-hosted n8n'de env: NODE_FUNCTION_ALLOW_EXTERNAL=xlsx  (restart gerekir)
const XLSX = require('xlsx');

// --- 1) Detaylari sample bazina genislet (Sheet 1 verisi) ---
const rows = [];
for (const item of $input.all()) {
  const d = item.json.data || item.json;            // detay {data:{...}} formatinda gelir
  const base = {
    submitter: d.user_email ?? null,                // user_email
    name:      d.name ?? null,                       // name
    id:        d.job_id ?? null,                     // job_id
    date:      d.submit_time ?? null,                // submit_time (UTC ISO)
    panel:     d.target_region_name ?? null,         // target_region_name
    status:    d.job_status_name ?? null,            // job_status_name
  };
  const samples = Array.isArray(d.samples) ? d.samples : [];
  if (samples.length === 0) {
    rows.push({ ...base, sample_id: null, sample_name: null });
  } else {
    for (const s of samples) {
      rows.push({ ...base, sample_id: s.id ?? null, sample_name: s.name ?? null });
    }
  }
}

// --- Sheet 1: Samples (kolon sirasi sabit) ---
const sheet1Header = ['submitter','name','id','date','panel','status','sample_id','sample_name'];

// --- Sheet 2: Repeats (sample_name, count) -> sadece count > 1 ---
const rc = {};
for (const r of rows) {
  const n = r.sample_name;
  if (n === null || n === undefined || n === '') continue;
  rc[n] = (rc[n] || 0) + 1;
}
const sheet2 = Object.entries(rc)
  .filter(([, c]) => c > 1)
  .sort((a, b) => b[1] - a[1])
  .map(([sample_name, count]) => ({ sample_name, count }));

// --- Sheet 3: Matris (satir=user_mail, sutun=panel, hucre=sample sayisi) ---
const panels = new Set();
const byUser = {};
for (const r of rows) {
  const u = r.submitter ?? '(unknown)';
  const p = r.panel ?? '(none)';
  panels.add(p);
  if (!byUser[u]) byUser[u] = {};
  byUser[u][p] = (byUser[u][p] || 0) + 1;
}
const panelList = [...panels].sort();
const sheet3 = Object.keys(byUser).sort().map((u) => {
  const row = { user_mail: u };
  for (const p of panelList) row[p] = byUser[u][p] || 0;
  return row;
});

// --- Workbook olustur ---
const wb = XLSX.utils.book_new();

const ws1 = XLSX.utils.json_to_sheet(
  rows.length ? rows : [{}], { header: sheet1Header }
);
XLSX.utils.book_append_sheet(wb, ws1, 'Samples');

const ws2 = XLSX.utils.json_to_sheet(
  sheet2.length ? sheet2 : [{ sample_name: '(no repeats)', count: '' }],
  { header: ['sample_name', 'count'] }
);
XLSX.utils.book_append_sheet(wb, ws2, 'Repeats');

const ws3 = XLSX.utils.json_to_sheet(
  sheet3.length ? sheet3 : [{ user_mail: '(no data)' }],
  { header: ['user_mail', ...panelList] }
);
XLSX.utils.book_append_sheet(wb, ws3, 'Matrix');

const base64 = XLSX.write(wb, { type: 'base64', bookType: 'xlsx' });
const stamp = DateTime.now().setZone('Europe/Istanbul').toFormat('yyyyLLdd');
const fileName = `archer_job_raporu_${stamp}.xlsx`;

return [{
  json: {
    total_samples: rows.length,
    repeat_names: sheet2.length,
    users: sheet3.length,
    panels: panelList.length,
  },
  binary: {
    data: {
      data: base64,
      mimeType: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      fileName,
      fileExtension: 'xlsx',
    },
  },
}];

